import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputLine = scanner.nextLine();
        StringBuilder result = new StringBuilder();
        int length = inputLine.length();
        boolean atFound = false;
        char[] inputChars = inputLine.toCharArray();

        // Check if '@' is present
        for (int i = 0; i < length; i++) {
            if (inputChars[i] == '@') {
                atFound = true;
            }
        }

        for (int i = 0; i < length; i++) {
            if (i + 2 < length && inputChars[i] == 'd' && inputChars[i + 1] == 'o' && inputChars[i + 2] == 't' && i != 0 && i != length - 3) {
                result.append('.');
                inputChars[i] = ' ';
                inputChars[i + 1] = ' ';
                inputChars[i + 2] = ' ';
            } else if (i + 1 < length && inputChars[i] == 'a' && inputChars[i + 1] == 't' && i != 0 && i != length - 2 && !atFound) {
                result.append('@');
                inputChars[i] = ' ';
                inputChars[i + 1] = ' ';
                atFound = true;
            } else if (inputChars[i] != ' ') {
                result.append(inputChars[i]);
            }
        }
        System.out.print(result.toString());
        scanner.close();
    }
}
